#include <bits/stdc++.h>
using namespace std;

/*
  Todas as K etiquetas (blocos disjuntos de C quadrados) devem ser coladas.
  Maximizar a soma descoberta <=> maximizar (soma dos quadrados nao cobertos).
  DP por camadas (numero de etiquetas usadas):
    dp[j][i] = maior soma descoberta nos primeiros i quadrados usando exatamente j etiquetas
    dp[j][i] = max(dp[j][i-1] + A[i],            // quadrado i descoberto
                   dp[j-1][i-C])                 // etiqueta cobre [i-C+1 .. i]
  Estado (j,i) so pode levar ao estado final (K,N) se:
    i >= j*C  (espaco para as j etiquetas)  e  i <= N - (K-j)*C  (espaco para as restantes)
  Logo cada camada tem exatamente N - K*C + 1 posicoes uteis.
  Complexidade: O(K * (N - K*C + 1)) <= ~N^2/4 = 2.5e7 no pior caso.
  Memoria: duas linhas de tamanho N+1.
*/
int main() {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) return 0;

    vector<long long> A(N + 1, 0), pre(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        int x;
        scanf("%d", &x);
        A[i] = x;
        pre[i] = pre[i - 1] + x;
    }

    if ((long long)K * C > N) K = (int)((long long)N / C); // defesa (restricoes garantem K*C <= N)

    const long long NEG_INF = LLONG_MIN / 4;
    vector<long long> prv(N + 1, 0), cur(N + 1, NEG_INF);

    for (int i = 0; i <= N; i++) prv[i] = pre[i]; // camada j = 0: nada coberto

    for (int j = 1; j <= K; j++) {
        int lo = j * C;
        int hi = N - (K - j) * C;
        for (int i = lo; i <= hi; i++) {
            long long best = prv[i - C];              // quadrado i coberto por etiqueta terminando em i
            if (i > lo) {                              // quadrado i descoberto
                long long alt = cur[i - 1] + A[i];
                if (alt > best) best = alt;
            }
            cur[i] = best;
        }
        swap(prv, cur);
    }

    printf("%lld\n", prv[N]);
    return 0;
}
